'use strict';

// MODULES //

var isRowMajor = require( '@stdlib/ndarray/base/assert/is-row-major-string' );
var isLayout = require( '@stdlib/blas/base/assert/is-layout' );
var isMatrixTranspose = require( '@stdlib/blas/base/assert/is-transpose-operation' );
var resolveOrder = require( '@stdlib/blas/base/layout-resolve-enum' );
var resolveTrans = require( '@stdlib/blas/base/transpose-operation-resolve-enum' );
var max = require( '@stdlib/math/base/special/fast/max' );
var format = require( '@stdlib/string/format' );
var addon = require( './../src/addon.node' );


// MAIN //

/**
* Performs the matrix-matrix operation `C = α*op(A)*op(B) + β*C`, where `op(X)` is either `op(X) = X` or `op(X) = X^T`, `α` and `β` are scalars, and `A`, `B`, and `C` are matrices, with `op(A)` an `M` by `K` matrix, `op(B)` a `K` by `N` matrix, and `C` an `M` by `N` matrix.
*
* @param {string} order - storage layout
* @param {string} transA - specifies whether `A` should be transposed, conjugate-transposed, or not transposed
* @param {string} transB - specifies whether `B` should be transposed, conjugate-transposed, or not transposed
* @param {NonNegativeInteger} M - number of rows in `op(A)` and `C`
* @param {NonNegativeInteger} N - number of columns in `op(B)` and `C`
* @param {NonNegativeInteger} K - number of columns in `op(A)` and rows in `op(B)`
* @param {number} alpha - scalar constant
* @param {Float64Array} A - first matrix
* @param {PositiveInteger} LDA - leading dimension of `A`
* @param {Float64Array} B - second matrix
* @param {PositiveInteger} LDB - leading dimension of `B`
* @param {number} beta - scalar constant
* @param {Float64Array} C - result matrix
* @param {PositiveInteger} LDC - leading dimension of `C`
* @throws {TypeError} first argument must be a valid order
* @throws {TypeError} second argument must be a valid transpose operation
* @throws {TypeError} third argument must be a valid transpose operation
* @throws {RangeError} fourth argument must be a nonnegative integer
* @throws {RangeError} fifth argument must be a nonnegative integer
* @throws {RangeError} sixth argument must be a nonnegative integer
* @throws {RangeError} ninth argument must be a valid stride
* @throws {RangeError} eleventh argument must be a valid stride
* @throws {RangeError} fourteenth argument must be a valid stride
* @returns {Float64Array} `C`
*
* @example
* var Float64Array = require( '@stdlib/array/float64' );
*
* var A = new Float64Array( [ 1.0, 2.0, 3.0, 4.0 ] );
* var B = new Float64Array( [ 1.0, 1.0, 0.0, 1.0 ] );
* var C = new Float64Array( [ 1.0, 2.0, 3.0, 4.0 ] );
*
* dgemm( 'row-major', 'no-transpose', 'no-transpose', 2, 2, 2, 1.0, A, 2, B, 2, 1.0, C, 2 );
* // C => <Float64Array>[ 2.0, 5.0, 6.0, 11.0 ]
*/
function dgemm( order, transA, transB, M, N, K, alpha, A, LDA, B, LDB, beta, C, LDC ) { // eslint-disable-line max-params, max-len
	var nrowsa;
	var nrowsb;
	var isrm;
	var valc;
	if ( !isLayout( order ) ) {
		throw new TypeError( format( 'invalid argument. First argument must be a valid order. Value: `%s`.', order ) );
	}
	if ( !isMatrixTranspose( transA ) ) {
		throw new TypeError( format( 'invalid argument. Second argument must be a valid transpose operation. Value: `%s`.', transA ) );
	}
	if ( !isMatrixTranspose( transB ) ) {
		throw new TypeError( format( 'invalid argument. Third argument must be a valid transpose operation. Value: `%s`.', transB ) );
	}
	if ( M < 0 ) {
		throw new RangeError( format( 'invalid argument. Fourth argument must be a nonnegative integer. Value: `%d`.', M ) );
	}
	if ( N < 0 ) {
		throw new RangeError( format( 'invalid argument. Fifth argument must be a nonnegative integer. Value: `%d`.', N ) );
	}
	if ( K < 0 ) {
		throw new RangeError( format( 'invalid argument. Sixth argument must be a nonnegative integer. Value: `%d`.', K ) );
	}
	isrm = isRowMajor( order );
	if (
		( isrm && transA === 'no-transpose' ) ||
		( !isrm && transA !== 'no-transpose' )
	) {
		nrowsa = K;
	} else {
		nrowsa = M;
	}
	if (
		( isrm && transB === 'no-transpose' ) ||
		( !isrm && transB !== 'no-transpose' )
	) {
		nrowsb = N;
	} else {
		nrowsb = K;
	}
	if ( LDA < max( 1, nrowsa ) ) {
		throw new RangeError( format( 'invalid argument. Ninth argument must be greater than or equal to max(1,%d). Value: `%d`.', nrowsa, LDA ) );
	}
	if ( LDB < max( 1, nrowsb ) ) {
		throw new RangeError( format( 'invalid argument. Eleventh argument must be greater than or equal to max(1,%d). Value: `%d`.', nrowsb, LDB ) );
	}
	if ( isrm ) {
		valc = N;
	} else {
		valc = M;
	}
	if ( LDC < max( 1, valc ) ) {
		throw new RangeError( format( 'invalid argument. Fourteenth argument must be greater than or equal to max(1,%d). Value: `%d`.', valc, LDC ) );
	}
	addon( resolveOrder( order ), resolveTrans( transA ), resolveTrans( transB ), M, N, K, alpha, A, LDA, B, LDB, beta, C, LDC );
	return C;
}


// EXPORTS //

module.exports = dgemm;
